SELECT count(*) FROM public.chartevents chartevents
  LEFT JOIN (SELECT DISTINCT d.charttime AS key1, d.stay_id AS key2, 1 AS hit FROM (SELECT DISTINCT charttime, stay_id FROM public.chartevents) d, public.icustays i, public.admissions a, public.patients p, public.inputevents ie WHERE a.hadm_id = i.hadm_id AND p.subject_id = a.subject_id AND p.anchor_age >= 70 AND ie.stay_id = i.stay_id AND ie.itemid = 222168 AND d.charttime >= ie.starttime AND d.charttime <= ie.endtime AND d.stay_id = i.stay_id) b1 ON chartevents.charttime = b1.key1 AND chartevents.stay_id = b1.key2
  LEFT JOIN (SELECT DISTINCT d.charttime AS key1, d.stay_id AS key2, 1 AS hit FROM (SELECT DISTINCT charttime, stay_id FROM public.chartevents) d, public.icustays i, public.transfers t, public.services s, public.procedures_icd pr WHERE t.hadm_id = i.hadm_id AND s.hadm_id = t.hadm_id AND s.curr_service = 'CSURG' AND pr.hadm_id = t.hadm_id AND d.charttime >= t.intime AND d.charttime <= t.outtime AND d.stay_id = i.stay_id) b2 ON chartevents.charttime = b2.key1 AND chartevents.stay_id = b2.key2
WHERE (b1.hit IS NOT NULL AND b2.hit IS NULL);
